  select count(*)
  into v_count
  from public.audit_log a
  where a.actor_id = p_actor
    and a.at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
    and a.action = any (v_actions);
  if v_count >= v_limit then
    raise exception 'agent_daily_limit';
  end if;
end;
